ion"], "derived": ["drv.interaction.overtake_pass_on_right"], "justification": "An observation inside the act lies after its beginning, the last observation of the window behind at which b was ahead of the subject with headings aligned (rel.bearing longitudinal component positive, rel.longitudinal_overlap negative, rel.same_direction), and at or before its recognition, while the subject's velocity (kin.velocity), exceeding b's along its heading, carries it up to and past b; before it b is still ahead and clear. These relations are computed from the two road users' kinematics, so the boundary reads their relative motion, never a place."}, "spans": {"s3": "throughout", "s4": "throughout", "s5": "throughout", "s8": "at_recognition", "s9": "at_recognition", "s10": "at_recognition", "s11": "throughout", "s12": "at_recognition", "s14": "at_recognition", "s16": "at_recognition", "s17": "at_recognition", "s18": "at_recognition", "s19": "at_recognition", "s20": "throughout", "s21": "throughout"}}, "literals": [{"span": "s4", "text": "two", "value": 2, "unit": "count"}, {"span": "s8", "text": "200 feet", "value": 200, "unit": "ft"}, {"span": "s11", "text": "two", "value": 2, "unit": "count"}], "param_proposals": [{"name": "p.overtake_window", "unit": "s", "value": 10.0, "convention": "the longest duration of an overtaking manoeuvre on an urban street, from having the overtaken vehicle ahead to having it behind", "source": "overtaking-manoeuvre durations in naturalistic driving studies"}, {"name": "p.overtake_same_direction_cos", "unit": "ratio", "value": 0.9, "convention": "cosine of the largest heading difference (about 25 degrees) at which two vehicles count as travelling in the same direction while one moves out to pass the other", "source": "lane-change heading angles in naturalistic driving data"}, {"name": "p.turn_window", "unit": "s", "value": 10.0, "convention": "the longest duration of a turn at a junction by a bicycle or a scooter, from the start of its heading change to its end", "source": "junction turning-time observations"}, {"name": "p.turn_heading_min", "unit": "deg", "value": 45.0, "convention": "the smallest heading change over the turn window at which a change of course counts as a turn rather than a lane change or a drift", "source": "intersection turning-geometry conventions"}, {"name": "p.u_turn_heading_min", "unit": "deg", "value": 135.0, "convention": "the smallest heading change magnitude over the turn window at which a turn counts as a reversal of direction", "source": "intersection turning-geometry conventions"}, {"name": "p.turn_yaw_rate_tol", "unit": "deg/s", "value": 3.0, "convention": "the yaw-rate magnitude at or below which a road user's heading counts as no longer turning: the yaw-rate noise floor of the source", "source": "yaw-rate noise of the acquisition source"}, {"name": "p.halt_speed_tolerance", "unit": "m/s", "value": 0.1, "convention": "the speed at or below which a sampled speed counts as no movement: the source's speed resolution", "source": "speed resolution of the acquisition source"}, {"name": "p.parking_min_duration", "unit": "s", "value": 180.0, "convention": "the longest halt counted as temporary, as for loading or unloading: a common time limit of a passenger loading zone", "source": "municipal passenger-loading-zone time limits"}], "gaps": [{"span": "s10", "kind": "atom", "proposal": "`st.private_way_entrance` | the place where a way in private ownership — a private road or driveway — meets the highway, through which a vehicle enters or leaves the highway; the junction of an alley, a public way, with another way is not one **Not a stand-in for:** an alley's junction or an intersection | general", "nearest": "st.driveway_or_alley_entrance — 'Not a stand-in for: which of them meets the highway there — the kind does not tell an alley's entrance from a private road's or driveway's'; st.alley — a way within a block, not the place where a private way meets the highway"}], "gap_resolutions": 